describe('Evaluation thresholds', () => {
  const reportFor = (evaluations, thresholds) =>
    generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });

  it('leaves the report unchanged without thresholds', () => {
    const evaluations = runEvaluations({ outputs: ['Hello'], references: ['hello'] });
    const report = reportFor(evaluations, undefined);
    expect(Object.keys(report)).toEqual(['metadata', 'metrics']);
    expect(toMarkdown(report)).not.toContain('Thresholds');
  });

  it('passes when the score meets the minimum and fails below it', () => {
    const evaluations = runEvaluations({
      outputs: ['a', 'b', 'c', 'x'],
      references: ['a', 'b', 'c', 'd'],
      metrics: [exactMatchMetric]
    });
    const atMin = reportFor(evaluations, { exact_match: 0.75 });
    expect(atMin.passed).toBe(true);
    expect(atMin.thresholds).toEqual([
      { metric: 'exact_match', min: 0.75, score: 0.75, passed: true }
    ]);

    const above = reportFor(evaluations, { exact_match: 0.8 });
    expect(above.passed).toBe(false);
    expect(above.thresholds[0]).toMatchObject({ score: 0.75, passed: false });
  });

  it('fails a threshold whose metric has no score', () => {
    const evaluations = runEvaluations({ outputs: ['Hello'], metrics: [exactMatchMetric] });
    const report = reportFor(evaluations, { exact_match: 0 });
    expect(report.passed).toBe(false);
    expect(report.thresholds).toEqual([
      { metric: 'exact_match', min: 0, score: null, passed: false }
    ]);
  });

  it('fails overall when any threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['a', 'b'],
      references: ['a', 'z'],
      metrics: [exactMatchMetric, lengthVarianceMetric]
    });
    const report = reportFor(evaluations, { length_variance: 0.9, exact_match: 0.9 });
    expect(report.passed).toBe(false);
    expect(report.thresholds.map((t) => [t.metric, t.passed])).toEqual([
      ['length_variance', true],
      ['exact_match', false]
    ]);

    const markdown = toMarkdown(report);
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('- **Result:** FAIL');
    expect(markdown).toContain('| length_variance | 0.9 | 1 | PASS |');
    expect(markdown).toContain('| exact_match | 0.9 | 0.5 | FAIL |');
  });

  it('supports custom metrics', () => {
